// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getResponseValue } from '@skyramp/skyramp';
import { createUser, deleteUser, createCollection, updateCollection, getCollectionMembers, getCollectionTransfer, createCollectionTransfer } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Request Body
    const usersPostRequestBody: string = `{
        "name": "Testbot New Owner",
        "password": "testbotpassword123",
        "username": "testbot-new-owner"
    }`;

    const usersPostResponse = await createUser(client, URL_localhost, usersPostRequestBody, "testbot-new-owner", 201);
    expect(usersPostResponse.statusCode, 'status code').toBe(201);
    expect(getResponseValue(usersPostResponse, "response.username"), 'username').toMatch(/^testbot-new-owner-/);
    expect(getResponseValue(usersPostResponse, "response.id"), 'id').toBeGreaterThan(0);
    const newOwnerUserId = getResponseValue(usersPostResponse, "response.id");

    // Request Body
    const collectionsPostRequestBody: string = `{
        "description": "testbot transfer fixture",
        "name": "Testbot Transfer Fixture"
    }`;

    const collectionsPostResponse = await createCollection(client, URL_localhost, collectionsPostRequestBody, 200);
    expect(collectionsPostResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsPostResponse, "response.name"), 'name').toBe("Testbot Transfer Fixture");
    expect(getResponseValue(collectionsPostResponse, "response.description"), 'description').toBe("testbot transfer fixture");
    expect(getResponseValue(collectionsPostResponse, "response.ownerId"), 'ownerId').toBeGreaterThan(0);
    const collectionId = getResponseValue(collectionsPostResponse, "response.id");
    const ownerUserId = getResponseValue(collectionsPostResponse, "response.ownerId");

    // Request Body
    const collectionsCollectionsPutRequestBody: string = `{
        "color": "#0ea5e9",
        "description": "testbot transfer fixture",
        "id": 6295,
        "isPublic": false,
        "members": [
            {
                "canCreate": false,
                "canDelete": false,
                "canUpdate": false,
                "userId": 6184
            }
        ],
        "name": "Testbot Transfer Fixture",
        "ownerId": 4073
    }`;

    const collectionsCollectionsPutResponse = await updateCollection(client, URL_localhost, collectionId, collectionsCollectionsPutRequestBody, ownerUserId, newOwnerUserId, 200);
    expect(collectionsCollectionsPutResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsCollectionsPutResponse, "response.id"), 'updated collection id').toBe(collectionId);
    expect(getResponseValue(collectionsCollectionsPutResponse, "response.ownerId"), 'owner before transfer').toBe(ownerUserId);

    const membersGetResponse = await getCollectionMembers(client, URL_localhost, collectionId, 200);
    expect(membersGetResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(membersGetResponse, "response").length, 'member count before transfer').toBe(1);
    expect(getResponseValue(membersGetResponse, "response.0.userId"), 'transfer target is a member').toBe(newOwnerUserId);
    expect(getResponseValue(membersGetResponse, "response.1"), 'second member').toBeNull();

    const transferGetResponse = await getCollectionTransfer(client, URL_localhost, collectionId, 405);
    expect(transferGetResponse.statusCode, 'status code').toBe(405);
    expect(getResponseValue(transferGetResponse, "response"), 'error body').toBe("Method not allowed.");

    // Request Body
    const transferPostRequestBody: string = `{
        "userId": 6184
    }`;

    // Request Body
    const transferPost1RequestBody: string = `{
        "toUserId": 999999
    }`;

    // Request Body
    const transferPost2RequestBody: string = `{
        "toUserId": 6184
    }`;

    const transferPostResponse = await createCollectionTransfer(client, URL_localhost, collectionId, transferPostRequestBody, {"userId": newOwnerUserId}, 400);
    expect(transferPostResponse.statusCode, 'status code').toBe(400);
    expect(getResponseValue(transferPostResponse, "response"), 'error body').toBe("toUserId is required.");

    const transferPost1Response = await createCollectionTransfer(client, URL_localhost, collectionId, transferPost1RequestBody, {}, 400);
    expect(transferPost1Response.statusCode, 'status code').toBe(400);
    expect(getResponseValue(transferPost1Response, "response"), 'error body').toBe("Transfer target must already be a member of the collection.");

    const transferPost2Response = await createCollectionTransfer(client, URL_localhost, collectionId, transferPost2RequestBody, {"toUserId": newOwnerUserId}, 200);
    expect(transferPost2Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(transferPost2Response, "response.id"), 'transferred collection id').toBe(collectionId);
    expect(getResponseValue(transferPost2Response, "response.name"), 'name').toBe("Testbot Transfer Fixture");
    expect(getResponseValue(transferPost2Response, "response.ownerId"), 'owner after transfer').toBe(newOwnerUserId);

    const usersUsersDeleteResponse = await deleteUser(client, URL_localhost, newOwnerUserId, 200);
    expect(usersUsersDeleteResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(usersUsersDeleteResponse, "response"), 'delete user body').toBe("User account and all related data deleted successfully.");
});
